/* ---------- Segmented control ---------- */
/* one choice from a few views of the same thing: the picked one sits on a white knob that slides to it. It is a tab
   list, so the arrow keys move along it and the panel under it changes with it */
.dm-sgc{width:100%;max-width:400px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:14px}
.dm-sgc-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);flex-wrap:wrap}
.dm-sgc-ht{display:flex;flex-direction:column;min-width:0}
.dm-sgc-ht b{font-weight:500;font-size:14px}
/* the range on the content's left edge; Today and the arrows at the right, the last arrow's glyph on the content's right edge
   with its hover circle reaching out round it */
.dm-sgc-bar{display:flex;align-items:center;gap:2px;margin:-4px 0 -6px}
.dm-sgc-r{flex:1;min-width:0;font-size:13px;color:var(--dm-fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-sgc-bar .dm-ib{width:28px;height:28px}
.dm-sgc-bar .dm-pill{margin-right:var(--dm-s-1)}
.dm-sgc-bar .dm-sgc-nx{margin-right:-8px}
.dm-sgc-seg{position:relative;display:inline-flex;padding:3px;border-radius:var(--dm-r-pill);background:var(--dm-chip);flex:none}
.dm-sgc-k{position:absolute;top:3px;bottom:3px;left:3px;width:0;border-radius:var(--dm-r-pill);background:var(--dm-raised);box-shadow:var(--dm-seg-k-shadow,var(--dm-shadow));transition:left .42s var(--dm-ease),width .42s var(--dm-ease)}
.dm-sgc-seg button{position:relative;z-index:1;height:30px;padding:0 14px;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);outline:0;transition:color .2s}
.dm-sgc-seg button[aria-selected="true"],.dm-sgc-seg button[aria-checked="true"]{color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.dm-sgc-seg button:hover{color:var(--dm-fg)}}
.dm-sgc-seg button:focus-visible{box-shadow:0 0 0 2px var(--dm-focus)}
/* the panel is as tall as the view on show, and eases to the next one's height (grow()): a day with one event is short, the
   month tall, and nothing keeps room for a view that isn't there */
.dm-sgc-p{position:relative;border-radius:var(--dm-r-in);outline:0}
.dm-sgc-p.dm-growing{overflow-clip-margin:10px}
.dm-sgc-p:focus-visible{box-shadow:0 0 0 2px var(--dm-focus)}
/* a new view crossfades over the one it replaces, so the panel is never empty between them */
.dm-sgc-in.dm-fresh{animation:dm-sgcin .24s var(--dm-ease) both}
.dm-sgc-in.dm-gone{position:absolute;inset:0 0 auto;pointer-events:none;animation:dm-sgcout .24s var(--dm-ease) both}
@keyframes dm-sgcin{from{opacity:0;transform:translateY(4px)}}
@keyframes dm-sgcout{to{opacity:0}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.dm-sgc :is(.dm-ib,.dm-pill):active,:root[data-style="clean"] .dm-sgc .dm-ib:active,:root [data-style="clean"] .dm-sgc .dm-ib:active,:root [data-style="clean"].dm-sgc .dm-ib:active{transform:none}
/* the day: its events in order, a plain list (they are not buttons, so no card behind them). The times sit in the same 52px
   column as the week's days, each bar is centred on the week's dot column and the titles start where the week's do */
.dm-sgc-day{display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-sgc-ev{display:flex;align-items:flex-start;gap:var(--dm-s-3);font-size:13px;line-height:18px}
.dm-sgc-ev>.dm-num{width:52px;flex:none}
.dm-sgc-ev i{width:3px;align-self:stretch;margin:0 1.5px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-c);flex:none}
.dm-sgc-ev .dm-t{flex:1;min-width:0;display:flex;flex-direction:column;margin-left:-4px}
.dm-sgc-ev .dm-t span{font-size:12px;line-height:17px;color:var(--dm-muted)}
.dm-sgc-none{padding:var(--dm-s-3) 0;font-size:13px;color:var(--dm-muted)}
/* the week: the five working days, one row each with its first event and a count of the rest. Each row's words sit on the
   content's edges and its hover fill reaches 8px out round them; today's date is the accent circle, as in Event calendar */
.dm-sgc-wk{display:flex;flex-direction:column;gap:var(--dm-s-1)}
.dm-sgc-wr{display:flex;align-items:center;gap:var(--dm-s-3);width:calc(100% + 16px);height:32px;margin:0 -8px;padding:0 8px;border-radius:var(--dm-r-sm);font-size:13px;text-align:left;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-sgc-wr:hover{background:var(--dm-row)}}
.dm-sgc-wr:focus-visible,.dm-sgc-mo .dm-d:focus-visible{outline:0;box-shadow:0 0 0 2px var(--dm-focus)}
.dm-sgc-wr .dm-d{width:52px;flex:none;display:flex;align-items:center;gap:4px;color:var(--dm-muted)}
.dm-sgc-wr .dm-d b{font-weight:400}
.dm-sgc-wr.dm-now .dm-d{color:var(--dm-fg)}
.dm-sgc-wr.dm-now .dm-d b{display:grid;place-items:center;min-width:22px;height:22px;margin:-2px 0 -2px -1px;padding:0 4px;border-radius:var(--dm-r-pill);background:var(--dm-accent);color:var(--dm-on-accent);font-size:12px;font-weight:500}
.dm-sgc-wr .dm-e{flex:1;min-width:0;display:flex;align-items:center;gap:var(--dm-s-2);white-space:nowrap}
.dm-sgc-wr .dm-e i{width:6px;height:6px;border-radius:50%;background:var(--dm-c);flex:none}
.dm-sgc-wr .dm-e span:last-child{min-width:0;overflow:hidden;text-overflow:ellipsis}
.dm-sgc-wr .dm-more{flex:none;font-size:12px;color:var(--dm-muted)}
.dm-sgc-wr.dm-none .dm-e{color:var(--dm-muted)}
/* the month: a dot on each day with something on, today the accent fill */
.dm-sgc-mo{display:grid;grid-template-columns:repeat(7,1fr);gap:2px var(--dm-s-1);font-size:12px;text-align:center}
.dm-sgc-mo .dm-w{font-size:11px;color:var(--dm-muted);padding-bottom:2px}
.dm-sgc-mo .dm-d{position:relative;height:26px;display:grid;place-items:center;border-radius:var(--dm-r-sm);color:var(--dm-fg2);transition:background var(--dm-t-fast)}
.dm-sgc-mo.dm-r6 .dm-d{height:22px}
@media (hover:hover) and (pointer:fine){.dm-sgc-mo .dm-d:hover{background:var(--dm-row)}}
.dm-sgc-mo .dm-d.dm-on{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
.dm-sgc-mo .dm-d.dm-e::after{content:"";position:absolute;bottom:2px;left:50%;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:var(--dm-accent-mark,var(--dm-accent))}
.dm-sgc-mo .dm-d.dm-now{background:var(--dm-accent);color:var(--dm-on-accent);font-weight:500}
@media (hover:hover) and (pointer:fine){.dm-sgc-mo .dm-d.dm-now:hover{background:var(--dm-accent);color:var(--dm-on-accent);font-weight:500}}
.dm-sgc-mo .dm-d.dm-now::after{background:var(--dm-on-accent)}
/* Clean (owner, 17 and 18 Nov): its content 16px in from every edge; the switch is Clean's (a white knob on a grey track,
   in the Clean section with the other switchers) */
:root[data-style="clean"] .dm-sgc.dm-panel,:root [data-style="clean"] .dm-sgc.dm-panel,:root [data-style="clean"].dm-sgc.dm-panel{padding:16px}
/* Clean (owner, 21 Nov, on the Pricing launch agenda: "no difference besides the corners, need to change a lot more"). The title
   and the switch sit in an off-white head strip under a hairline, the switch Clean's monochrome one; Today is a flat hairline
   pill and ‹ › ghost circles. The events are rows under one gliding highlight (hoverGlide), their hover reaching 8px out round
   their words as the week's rows do; their bars and dots take the labels' vivid marks (a step brighter than the labels' text
   colours, 3:1 on the card), and the times stand muted in one tabular column. A new view crossfades at Clean's pace while the
   panel grows or shrinks to it; a picked day in the month takes the one selected fill. The rows' hover room makes up the
   foot, so the last row's words sit 16px from it in every view */
:root[data-style="clean"] .dm-sgc.dm-panel,:root [data-style="clean"] .dm-sgc.dm-panel,:root [data-style="clean"].dm-sgc.dm-panel{padding:0 16px 10px}
:root[data-style="clean"] .dm-sgc-h,:root [data-style="clean"] .dm-sgc-h,:root [data-style="clean"].dm-sgc-h{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);margin:0 -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .dm-sgc-td,:root [data-style="clean"] .dm-sgc-td,:root [data-style="clean"].dm-sgc-td{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-sgc-td:hover,:root [data-style="clean"] .dm-sgc-td:hover,:root [data-style="clean"].dm-sgc-td:hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .dm-sgc-bar .dm-ib,:root [data-style="clean"] .dm-sgc-bar .dm-ib,:root [data-style="clean"].dm-sgc-bar .dm-ib{border-radius:50%}
/* (the last arrow, a control, ends on the content's right edge, as a strip's last control does) */
:root[data-style="clean"] .dm-sgc-bar .dm-sgc-nx,:root [data-style="clean"] .dm-sgc-bar .dm-sgc-nx,:root [data-style="clean"].dm-sgc-bar .dm-sgc-nx{margin-right:0}
:root[data-style="clean"] :is(.dm-sgc-ev,.dm-sgc-wr .dm-e),:root [data-style="clean"] :is(.dm-sgc-ev,.dm-sgc-wr .dm-e),:root [data-style="clean"]:is(.dm-sgc-ev,.dm-sgc-wr .dm-e){--dm-pb:var(--dm-av-b);--dm-pl:var(--dm-av-l);--dm-pm:var(--dm-c3);--dm-pt:var(--dm-c6)}
:root[data-style="clean"] .dm-sgc-day,:root [data-style="clean"] .dm-sgc-day,:root [data-style="clean"].dm-sgc-day{gap:2px}
:root[data-style="clean"] .dm-sgc-ev,:root [data-style="clean"] .dm-sgc-ev,:root [data-style="clean"].dm-sgc-ev{margin:0 -8px;padding:6px 8px;border-radius:10px}
:root[data-style="clean"] .dm-sgc-ev>.dm-num,:root [data-style="clean"] .dm-sgc-ev>.dm-num,:root [data-style="clean"].dm-sgc-ev>.dm-num,:root[data-style="clean"] .dm-sgc-wr .dm-d,:root [data-style="clean"] .dm-sgc-wr .dm-d,:root [data-style="clean"].dm-sgc-wr .dm-d{color:var(--dm-muted);font-variant-numeric:tabular-nums}
:root[data-style="clean"] .dm-sgc-wr,:root [data-style="clean"] .dm-sgc-wr,:root [data-style="clean"].dm-sgc-wr{border-radius:10px;transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-sgc-mo .dm-d,:root [data-style="clean"] .dm-sgc-mo .dm-d,:root [data-style="clean"].dm-sgc-mo .dm-d{border-radius:var(--dm-r-pill);transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-sgc-mo .dm-d.dm-on,:root [data-style="clean"] .dm-sgc-mo .dm-d.dm-on,:root [data-style="clean"].dm-sgc-mo .dm-d.dm-on{background:var(--dm-row-on);box-shadow:none}
/* (the month's days are boxes with no fill until hovered: a little room under the last week keeps its numbers 16px off the foot) */
:root[data-style="clean"] .dm-sgc-mo,:root [data-style="clean"] .dm-sgc-mo,:root [data-style="clean"].dm-sgc-mo{padding-bottom:5px}
:root[data-style="clean"] .dm-sgc-in.dm-fresh,:root [data-style="clean"] .dm-sgc-in.dm-fresh,:root [data-style="clean"].dm-sgc-in.dm-fresh{animation:dm-sgcin var(--dm-t-fast) var(--dm-ease) both}
